"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type BeaconStreamProps = {
  className?: string;
  label?: string;
  bars?: number;
};

/**
 * Streaming status beacon — equalizer-style bars for live agent output.
 */
function BeaconStream({
  className,
  label = "Streaming",
  bars = 7,
}: BeaconStreamProps) {
  const count = Math.min(12, Math.max(3, bars));
  return (
    <div
      className={cn(
        "inline-flex items-center gap-3 rounded-full border border-border bg-card px-3 py-2 shadow-[var(--shadow-soft)]",
        className,
      )}
    >
      <div className="flex h-5 items-end gap-0.5">
        {Array.from({ length: count }, (_, i) => (
          <span
            key={i}
            className="w-1 origin-bottom rounded-full bg-primary animate-[joy-beacon_1.8s_ease-in-out_infinite]"
            style={{
              height: "100%",
              animationDelay: `${i * 0.12}s`,
            }}
          />
        ))}
      </div>
      <span className="text-xs font-medium text-muted-foreground">{label}</span>
    </div>
  );
}

export { BeaconStream };
